import { logger } from "../utils/logger.js";
import { callMemoryTool } from "./mcp-client.js";
function isRecord(value) {
    return typeof value === "object" && value !== null && !Array.isArray(value);
}
function asString(value) {
    return typeof value === "string" && value.length > 0 ? value : undefined;
}
function asNumber(value) {
    return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}
function asBoolean(value) {
    return typeof value === "boolean" ? value : undefined;
}
function parseJsonRecord(raw) {
    try {
        const parsed = JSON.parse(raw);
        return isRecord(parsed) ? parsed : null;
    }
    catch {
        return null;
    }
}
function parseReasonCode(raw) {
    if (!isRecord(raw.summary))
        return undefined;
    const summary = raw.summary;
    if (!isRecord(summary.partial))
        return undefined;
    const partial = summary.partial;
    const code = partial.reason_code;
    if (code === null)
        return null;
    return typeof code === "string" ? code : undefined;
}
function mapReasonCodeToStatus(reasonCode) {
    if (reasonCode === null || reasonCode === undefined)
        return "ok";
    switch (reasonCode) {
        case "unsupported": return "unsupported";
        case "degraded": return "degraded";
        case "stale": return "stale";
        case "generation_mismatch": return "generation_mismatch";
        case "partial": return "partial";
        default: return "partial";
    }
}
function parseLearningMetadata(raw) {
    if (!isRecord(raw))
        return null;
    const learning = raw.learning;
    if (!isRecord(learning))
        return null;
    return {
        schema_version: asNumber(learning.schema_version) ?? 0,
        kind: asString(learning.kind),
        status: asString(learning.status),
        confidence: asNumber(learning.confidence),
        scope: isRecord(learning.scope) ? learning.scope : undefined,
        source: isRecord(learning.source) ? learning.source : undefined,
        ...learning,
    };
}
function parseLearningRecord(raw) {
    if (!isRecord(raw))
        return null;
    const id = asString(raw.id);
    const content = asString(raw.content);
    if (!id || content === undefined)
        return null;
    const metadata = parseLearningMetadata(raw.metadata);
    if (!metadata)
        return null;
    return {
        id,
        content,
        memory_type: asString(raw.memory_type),
        metadata: {
            learning: metadata,
            ...(isRecord(raw.metadata) ? raw.metadata : {}),
        },
        valid_until: typeof raw.valid_until === "string" ? raw.valid_until : null,
        invalidation_reason: asString(raw.invalidation_reason) ?? null,
        superseded_by: asString(raw.superseded_by) ?? null,
        raw: raw,
    };
}
function parseLearningSummary(raw) {
    if (!isRecord(raw))
        return undefined;
    return {
        schema_version: asNumber(raw.schema_version),
        kind: asString(raw.kind),
        status: asString(raw.status),
        lifecycle_state: asString(raw.lifecycle_state),
        included_in_default_list: asBoolean(raw.included_in_default_list),
        included_in_default_search: asBoolean(raw.included_in_default_search),
        injectable_by_default: asBoolean(raw.injectable_by_default),
        result_count: asNumber(raw.result_count),
        default_included_status: Array.isArray(raw.default_included_status)
            ? raw.default_included_status.filter((s) => typeof s === "string")
            : undefined,
        raw,
    };
}
function parseLearningReplacementLineage(raw) {
    if (!isRecord(raw))
        return undefined;
    return {
        chain_ids: Array.isArray(raw.chain_ids)
            ? raw.chain_ids.filter((s) => typeof s === "string")
            : undefined,
        depth: asNumber(raw.depth),
        terminal_replacement_id: asString(raw.terminal_replacement_id),
        cycle_detected: asBoolean(raw.cycle_detected),
        truncated: asBoolean(raw.truncated),
        raw,
    };
}
function isUnknownToolError(err) {
    const msg = String(err).toLowerCase();
    return msg.includes("unknown tool") || msg.includes("tool not found") || msg.includes("not supported");
}
function classifyCallError(err) {
    const msg = String(err);
    if (msg.includes("Memory server unavailable"))
        return "unavailable";
    return "failed";
}
async function callLearningTool(config, toolName, args) {
    try {
        const text = await callMemoryTool(config, toolName, args);
        return parseJsonRecord(text);
    }
    catch (err) {
        if (isUnknownToolError(err))
            return "unsupported";
        throw err;
    }
}
export async function createLearningMemory(config, args) {
    try {
        const result = await callLearningTool(config, "learning_memory_create", args);
        if (result === "unsupported")
            return { status: "unsupported" };
        if (!result)
            return { status: "failed" };
        const reasonCode = parseReasonCode(result);
        const status = mapReasonCodeToStatus(reasonCode);
        return {
            status,
            reason_code: reasonCode,
            record: parseLearningRecord(result.record) ?? undefined,
            learning_summary: parseLearningSummary(result.learning_summary),
            raw: result,
        };
    }
    catch (err) {
        logger.error("learning_memory_create failed", { error: String(err) });
        return { status: classifyCallError(err) };
    }
}
export async function getLearningMemory(config, args) {
    try {
        const result = await callLearningTool(config, "learning_memory_get", args);
        if (result === "unsupported")
            return { status: "unsupported" };
        if (!result)
            return { status: "failed" };
        const reasonCode = parseReasonCode(result);
        const status = mapReasonCodeToStatus(reasonCode);
        return {
            status,
            reason_code: reasonCode,
            record: parseLearningRecord(result.record) ?? undefined,
            learning_summary: parseLearningSummary(result.learning_summary),
            raw: result,
        };
    }
    catch (err) {
        logger.error("learning_memory_get failed", { error: String(err), id: args.id });
        return { status: classifyCallError(err) };
    }
}
export async function listLearningMemories(config, args) {
    try {
        const result = await callLearningTool(config, "learning_memory_list", args);
        if (result === "unsupported")
            return { status: "unsupported", records: [] };
        if (!result)
            return { status: "failed", records: [] };
        const reasonCode = parseReasonCode(result);
        const status = mapReasonCodeToStatus(reasonCode);
        const records = Array.isArray(result.records)
            ? result.records.map(parseLearningRecord).filter((r) => r !== null)
            : [];
        return {
            status,
            reason_code: reasonCode,
            records,
            learning_summary: parseLearningSummary(result.learning_summary),
            raw: result,
        };
    }
    catch (err) {
        logger.error("learning_memory_list failed", { error: String(err) });
        return { status: classifyCallError(err), records: [] };
    }
}
export async function searchLearningMemories(config, args) {
    try {
        const result = await callLearningTool(config, "learning_memory_search", args);
        if (result === "unsupported")
            return { status: "unsupported", records: [] };
        if (!result)
            return { status: "failed", records: [] };
        const reasonCode = parseReasonCode(result);
        const status = mapReasonCodeToStatus(reasonCode);
        const records = Array.isArray(result.records)
            ? result.records.map(parseLearningRecord).filter((r) => r !== null)
            : [];
        return {
            status,
            reason_code: reasonCode,
            records,
            learning_summary: parseLearningSummary(result.learning_summary),
            raw: result,
        };
    }
    catch (err) {
        logger.error("learning_memory_search failed", { error: String(err) });
        return { status: classifyCallError(err), records: [] };
    }
}
